.accordion-trigger:hover { background: var(--color-bg-hover); }
.accordion-content { overflow: hidden; transition: max-height 0.3s ease; }

/* Nav */
.nav-link {
  color: var(--color-text-secondary);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: 6px;
  transition: all 0.15s;
}
.nav-link:hover, .nav-link-active { color: var(--color-text-primary); }
.nav-link-active { background: var(--color-bg-hover); }

