@import "tailwindcss";

@theme {
  --color-bg-primary: #0F0F0F;
  --color-bg-secondary: #1A1A2E;
  --color-bg-tertiary: #16213E;
  --color-bg-card: #1E1E32;
  --color-bg-hover: #252545;
  --color-accent: #2962FF;
  --color-accent-hover: #3D75FF;
  --color-red: #F7525F;
  --color-red-dim: rgba(247, 82, 95, 0.15);
  --color-green: #00C853;
  --color-green-dim: rgba(0, 200, 83, 0.15);
  --color-text-primary: #F0F0F5;
  --color-text-secondary: #9CA3AF;
  --color-text-muted: #6B7280;
  --color-border: #2A2A4A;
  --color-border-light: #353560;
  --font-sans: 'DM Sans', 'Inter', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'DM Mono', monospace;
}

@layer base {
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: var(--font-sans);
    background: var(--color-bg-primary);
    color: var(--color-text-primary);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: var(--color-bg-primary); }
  ::-webkit-scrollbar-thumb { background: var(--color-border); border-radius: 3px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--color-border-light); }
}

@layer components {
  .btn-primary {
    background: var(--color-accent);
    color: white;
    padding: 10px 24px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 14px;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    gap: 8px;
  }
  .btn-primary:hover { background: var(--color-accent-hover); transform: translateY(-1px); }
  .btn-secondary {
    background: transparent;
    color: var(--color-text-primary);
    padding: 10px 24px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 14px;
    cursor: pointer;
    border: 1px solid var(--color-border);
    transition: all 0.2s;
    display: inline-flex;
    align-items: center;
    gap: 8px;
  }
  .btn-secondary:hover { border-color: var(--color-accent); color: var(--color-accent); }
  .btn-sm {
    padding: 4px 10px;
    font-size: 12px;
    border-radius: 4px;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: all 0.15s;
  }
  .badge-green {
    background: var(--color-green-dim);
    color: var(--color-green);
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 600;
  }
  .badge-red {
    background: var(--color-red-dim);
    color: var(--color-red);
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 600;
  }
  .ticker-up { color: var(--color-green); }
  .ticker-down { color: var(--color-red); }
  .card {
    background: var(--color-bg-card);
    border: 1px solid var(--color-border);
    border-radius: 10px;
    transition: border-color 0.2s;
  }
  .card:hover { border-color: var(--color-border-light); }
  .tab {
    padding: 6px 14px;
    border-radius: 6px;
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    border: none;
    background: transparent;
    color: var(--color-text-secondary);
    transition: all 0.15s;
    white-space: nowrap;
  }
  .tab:hover { color: var(--color-text-primary); background: var(--color-bg-hover); }
  .tab-active {
    background: var(--color-accent);
    color: white;
  }
  .tab-active:hover { background: var(--color-accent-hover); color: white; }
  .sparkline-up { stroke: var(--color-green); fill: none; }
  .sparkline-down { stroke: var(--color-red); fill: none; }
  .toolbar-btn {
    padding: 6px 10px;
    border-radius: 6px;
    font-size: 12px;
    cursor: pointer;
    border: 1px solid var(--color-border);
    background: var(--color-bg-card);
    color: var(--color-text-secondary);
    transition: all 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 4px;
  }
  .toolbar-btn:hover { color: var(--color-text-primary); border-color: var(--color-border-light); }
  .toolbar-btn-active { background: var(--color-accent); color: white; border-color: var(--color-accent); }
}

/* Candlestick chart */
.candle-up { fill: var(--color-green); stroke: var(--color-green); }
.candle-down { fill: var(--color-red); stroke: var(--color-red); }
.grid-line { stroke: var(--color-border); stroke-width: 0.5; stroke-dasharray: 4 4; }
.chart-axis { stroke: var(--color-text-muted); stroke-width: 1; fill: var(--color-text-muted); font-size: 10px; font-family: var(--font-mono); }

/* Animations */
@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.animate-in { animation: fadeIn 0.3s ease-out; }

@keyframes pulse-glow { 0%, 100% { box-shadow: 0 0 0 0 rgba(41, 98, 255, 0.4); } 50% { box-shadow: 0 0 0 6px rgba(41, 98, 255, 0); } }
.pulse-glow { animation: pulse-glow 2s infinite; }

/* Accordion */
.accordion-trigger {
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 10px 12px;
  background: var(--color-bg-tertiary);
  border: none;
  color: var(--color-text-primary);
  font-size: 13px;
  font-weight: 600;
  border-radius: 6px;
  transition: background 0.15s;
  font-family: var(--font-sans);
}
.accordion-trigger:hover { background: var(--color-bg-hover); }
.accordion-content { overflow: hidden; transition: max-height 0.3s ease; }

/* Nav */
.nav-link {
  color: var(--color-text-secondary);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: 6px;
  transition: all 0.15s;
}
.nav-link:hover, .nav-link-active { color: var(--color-text-primary); }
.nav-link-active { background: var(--color-bg-hover); }

/* Broker tier badges */
.tier-platinum { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; }
.tier-gold { background: linear-gradient(135deg, #f5af19 0%, #f12711 100%); color: white; }

/* Responsive */
@media (max-width: 1200px) {
  .watchlist-sidebar { display: none; }
  .chart-area { width: 100%; }
}
@media (max-width: 768px) {
  .market-ticker { flex-wrap: wrap; gap: 8px; }
  .hero-title { font-size: 28px; }
  .hero-subtitle { font-size: 16px; }
  .page-grid { grid-template-columns: 1fr; }
}

