import { useMemo } from 'react';

interface MiniChartProps {
  positive: boolean;
  width?: number;
  height?: number;
  bars?: number;
}

export default function MiniChart({ positive, width = 80, height = 30, bars = 12 }: MiniChartProps) {
  const pathData = useMemo(() => {
    const data = Array.from({ length: bars }, (_, i) => {
      const trend = positive ? (i / bars) * 0.6 : -(i / bars) * 0.6;
      return 0.5 + trend + (Math.random() - 0.5) * 0.3;
    });
    const max = Math.max(...data);
    const min = Math.min(...data);
    const range = max - min || 1;
    const points = data.map((d, i) => {
      const x = (i / (bars - 1)) * width;
      const y = height - ((d - min) / range) * (height - 4) - 2;
      return `${x},${y}`;
    });
    return `M${points.join(' L')}`;
  }, [positive, width, height, bars]);

  const color = positive ? '#00C853' : '#F7525F';

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      <path d={pathData} stroke={color} strokeWidth="1.5" fill="none" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

