import { useMemo } from 'react';

interface CandlePoint {
  open: number; high: number; low: number; close: number;
}

interface CandlestickChartProps {
  data: CandlePoint[];
  width?: number;
  height?: number;
}

export default function CandlestickChart({ data, width = 900, height = 400 }: CandlestickChartProps) {
  const elements = useMemo(() => {
    const padding = { top: 20, right: 20, bottom: 30, left: 60 };
    const chartW = width - padding.left - padding.right;
    const chartH = height - padding.top - padding.bottom;
    const allPrices = data.flatMap(d => [d.high, d.low]);
    const min = Math.min(...allPrices);
    const max = Math.max(...allPrices);
    const range = max - min || 1;
    const candleW = Math.max(4, chartW / data.length * 0.65);
    const gap = chartW / data.length;

    const toY = (price: number) => padding.top + chartH - ((price - min) / range) * chartH;
    const toX = (i: number) => padding.left + gap * i + gap / 2;

    const candles = data.map((d, i) => {
      const x = toX(i);
      const openY = toY(d.open);
      const closeY = toY(d.close);
      const highY = toY(d.high);
      const lowY = toY(d.low);
      const isUp = d.close >= d.open;
      const color = isUp ? '#00C853' : '#F7525F';
      const bodyTop = Math.min(openY, closeY);
      const bodyH = Math.max(Math.abs(closeY - openY), 1);
      return { x, openY, closeY, highY, lowY, bodyTop, bodyH, candleW, color, isUp };
    });

    // Grid lines
    const gridLines = [];
    for (let i = 0; i <= 5; i++) {
      const y = padding.top + (chartH / 5) * i;
      const price = max - ((max - min) / 5) * i;
      gridLines.push({ y, price });
    }

    return { candles, gridLines, padding, chartW, chartH };
  }, [data, width, height]);

  if (width === 0 || height === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full" preserveAspectRatio="xMidYMid meet">
      {elements.gridLines.map((g, i) => (
        <g key={i}>
          <line x1={elements.padding.left} y1={g.y} x2={width - elements.padding.right} y2={g.y} className="grid-line" />
          <text x={elements.padding.left - 8} y={g.y + 4} textAnchor="end" className="chart-axis">{g.price.toFixed(0)}</text>
        </g>
      ))}
      {elements.candles.map((c, i) => (
        <g key={i}>
          <line x1={c.x} y1={c.highY} x2={c.x} y2={c.lowY} stroke={c.color} strokeWidth="1" />
          <rect x={c.x - c.candleW / 2} y={c.bodyTop} width={c.candleW} height={c.bodyH} fill={c.isUp ? c.color : c.color} stroke={c.color} strokeWidth="0.5" />
        </g>
      ))}
    </svg>
  );
}

