import { useState, useMemo } from 'react';
import CandlestickChart from '../components/CandlestickChart';
import { watchlistData, stockDetail, stockFinancials, chartTimeframes } from '../config/site';

function generateCandleData(days: number): { open: number; high: number; low: number; close: number }[] {
  const data = [];
  let price = 255;
  for (let i = 0; i < days; i++) {
    const volatility = 2 + Math.random() * 4;
    const open = price;
    const close = open + (Math.random() - 0.48) * volatility * 3;
    const high = Math.max(open, close) + Math.random() * volatility;
    const low = Math.min(open, close) - Math.random() * volatility;
    data.push({ open: +open.toFixed(2), high: +high.toFixed(2), low: +low.toFixed(2), close: +close.toFixed(2) });
    price = close;
  }
  return data;
}

export default function Chart() {
  const [timeframe, setTimeframe] = useState(4);
  const [expandedCats, setExpandedCats] = useState<Set<string>>(new Set(['Indices', 'Stocks', 'Futures', 'Forex', 'Crypto']));
  const [detailTab, setDetailTab] = useState<'annual' | 'quarterly'>('annual');

  const daysMap = [1, 5, 21, 63, 126, 252, 365, 1260, 2520];
  const candleData = useMemo(() => generateCandleData(daysMap[timeframe]), [timeframe]);

  const toggleCat = (cat: string) => {
    const next = new Set(expandedCats);
    if (next.has(cat)) next.delete(cat); else next.add(cat);
    setExpandedCats(next);
  };

  const isPositive = !stockDetail.changePct.startsWith('−');

  return (
    <div className="max-w-[1440px] mx-auto px-4 sm:px-6 py-4">
      {/* Toolbar */}
      <div className="flex items-center gap-2 mb-4 flex-wrap">
        <div className="flex items-center gap-1 p-1 bg-[#1E1E32] rounded-lg border border-[#2A2A4A]">
          {chartTimeframes.map((tf, i) => (
            <button key={tf} className={`toolbar-btn ${i === timeframe ? 'toolbar-btn-active' : ''}`} onClick={() => setTimeframe(i)}>{tf}</button>
          ))}
        </div>
        <div className="h-6 w-px bg-[#2A2A4A] mx-1" />
        <button className="toolbar-btn"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg> Indicators</button>
        <button className="toolbar-btn"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 20V10M18 20V4M6 20v-4"/></svg> Compare</button>
        <button className="toolbar-btn"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg> Layout</button>
        <span className="ml-auto text-xs text-[#6B7280] font-mono">AAPL · NASDAQ</span>
      </div>

      <div className="flex gap-4">
        {/* Watchlist Sidebar */}
        <div className="watchlist-sidebar w-60 shrink-0">
          <div className="card p-0 overflow-hidden">
            <div className="p-3 bg-[#16213E] border-b border-[#2A2A4A]">
              <div className="flex justify-between items-center">
                <span className="text-sm font-semibold text-white">Watchlist</span>
                <button className="text-xs text-[#2962FF] hover:text-[#3D75FF]">+ Add</button>
              </div>
            </div>
            {Object.entries(watchlistData).map(([category, items]) => (
              <div key={category} className="border-b border-[#2A2A4A] last:border-b-0">
                <button className="accordion-trigger rounded-none border-b-0" onClick={() => toggleCat(category)}>
                  <span>{category}</span>
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ transform: expandedCats.has(category) ? 'rotate(180deg)' : 'rotate(0)' }}>
                    <path d="M6 9l6 6 6-6"/>
                  </svg>
                </button>
                <div className={`accordion-content ${expandedCats.has(category) ? 'max-h-[500px]' : 'max-h-0'}`}>
                  {items.map(item => (
                    <div key={item.symbol} className="flex items-center justify-between px-3 py-2 hover:bg-[#252545] cursor-pointer transition-colors text-xs border-t border-[#2A2A4A]">
                      <span className="font-mono font-semibold text-white w-16">{item.symbol}</span>
                      <span className="font-mono text-white w-20 text-right">{item.last}</span>
                      <span className={`font-mono w-16 text-right ${item.positive ? 'ticker-up' : 'ticker-down'}`}>{item.chgPct}%</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Chart Area */}
        <div className="flex-1 min-w-0">
          {/* Stock Detail Header */}
          <div className="card p-4 mb-4">
            <div className="flex items-start justify-between flex-wrap gap-4">
              <div>
                <div className="flex items-center gap-3 mb-1">
                  <h1 className="text-2xl font-bold text-white">{stockDetail.ticker}</h1>
                  <span className="text-sm text-[#9CA3AF]">{stockDetail.company} · {stockDetail.exchange}</span>
                </div>
                <div className="flex items-baseline gap-3">
                  <span className="text-3xl font-bold font-mono text-white">{stockDetail.price}</span>
                  <span className="text-sm text-[#9CA3AF]">USD</span>
                  <span className={`text-lg font-mono font-semibold ${isPositive ? 'ticker-up' : 'ticker-down'}`}>
                    {stockDetail.change} ({stockDetail.changePct}%)
                  </span>
                </div>
              </div>
              <div className="flex items-start gap-6 text-xs">
                <div><div className="text-[#6B7280]">Volume</div><div className="font-mono text-white mt-0.5">{stockDetail.volume}</div></div>
                <div><div className="text-[#6B7280]">Avg Vol (30D)</div><div className="font-mono text-white mt-0.5">{stockDetail.avgVolume}</div></div>
                <div><div className="text-[#6B7280]">Market Cap</div><div className="font-mono text-white mt-0.5">{stockDetail.marketCap}</div></div>
                <div><div className="text-[#6B7280]">Pre-Market</div><div className="font-mono ticker-up mt-0.5">{stockDetail.preMarket} (+{stockDetail.preMarketChange}%)</div></div>
              </div>
            </div>
            <div className="mt-3 pt-3 border-t border-[#2A2A4A] flex items-center gap-2 text-xs">
              <span className="text-[#6B7280]">Next earnings:</span>
              <span className="text-white font-medium">{stockDetail.nextEarnings}</span>
              <span className="text-[#2962FF] cursor-pointer hover:underline ml-2">Add to calendar</span>
            </div>
          </div>

          {/* Candlestick Chart */}
          <div className="card p-3 mb-4" style={{ height: '420px' }}>
            <CandlestickChart data={candleData} width={900} height={400} />
          </div>

          {/* Headline */}
          <div className="card p-3 mb-4 bg-[#2962FF]/5 border-[#2962FF]/20">
            <p className="text-sm text-white">{stockDetail.headline}</p>
          </div>

          {/* Detail Panel Tabs */}
          <div className="card p-4 mb-4">
            <div className="flex items-center gap-1 mb-4">
              <div className="flex gap-1 p-1 bg-[#0F0F0F] rounded-lg">
                <button className={`tab ${detailTab === 'annual' ? 'tab-active' : ''}`} onClick={() => setDetailTab('annual')}>Annual</button>
                <button className={`tab ${detailTab === 'quarterly' ? 'tab-active' : ''}`} onClick={() => setDetailTab('quarterly')}>Quarterly</button>
              </div>
            </div>
            {/* Income Statement Simulated */}
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead>
                  <tr className="text-[#6B7280] border-b border-[#2A2A4A]">
                    <th className="text-left py-2 px-3 font-medium">Metric</th>
                    {detailTab === 'annual' ? (
                      <>
                        <th className="text-right py-2 px-3 font-mono font-medium">FY 2025</th>
                        <th className="text-right py-2 px-3 font-mono font-medium">FY 2024</th>
                        <th className="text-right py-2 px-3 font-mono font-medium">FY 2023</th>
                        <th className="text-right py-2 px-3 font-mono font-medium">FY 2022</th>
                      </>
                    ) : (
                      <>
                        <th className="text-right py-2 px-3 font-mono font-medium">Q1 2026</th>
                        <th className="text-right py-2 px-3 font-mono font-medium">Q4 2025</th>
                        <th className="text-right py-2 px-3 font-mono font-medium">Q3 2025</th>
                        <th className="text-right py-2 px-3 font-mono font-medium">Q2 2025</th>
                      </>
                    )}
                  </tr>
                </thead>
                <tbody>
                  {[
                    ['Revenue', '124.3B', '119.6B', '108.2B', '99.8B'],
                    ['Gross Profit', '56.8B', '54.2B', '48.7B', '43.3B'],
                    ['Operating Income', '31.2B', '29.8B', '26.4B', '23.1B'],
                    ['Net Income', '25.7B', '24.1B', '21.5B', '18.9B'],
                    ['EPS (Diluted)', '$6.57', '$6.14', '$5.45', '$4.78'],
                    ['EBITDA', '35.4B', '33.8B', '30.1B', '26.5B'],
                  ].map((row, i) => (
                    <tr key={i} className="border-b border-[#2A2A4A] hover:bg-[#252545] transition-colors">
                      <td className="py-2.5 px-3 text-[#9CA3AF]">{row[0]}</td>
                      {row.slice(1).map((val, j) => (
                        <td key={j} className="py-2.5 px-3 text-right font-mono text-white">{val}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Key Financials */}
          <div className="card p-4">
            <h3 className="text-sm font-semibold text-white mb-3">Key Financials</h3>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
              {stockFinancials.map((item, i) => (
                <div key={i} className="p-3 bg-[#16213E] rounded-lg">
                  <div className="text-xs text-[#6B7280] mb-1">{item.label}</div>
                  <div className={`text-sm font-semibold font-mono ${
                    item.value.startsWith('+') ? 'ticker-up' :
                    item.value.startsWith('−') ? 'ticker-down' :
                    'text-white'
                  }`}>{item.value}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

